fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    // If there are 0 or 1 elements, nothing to insert.
    if n <= 1 {
        return numbers;
    }

    // We know the resulting length will be 2*n - 1.
    let mut result = Vec::with_capacity(2 * n - 1);
    let mut iter = numbers.into_iter().peekable();

    while let Some(num) = iter.next() {
        // Push the next number.
        result.push(num);
        // If there's still more numbers coming, push the delimiter.
        if iter.peek().is_some() {
            result.push(delimiter);
        }
    }

    result
}

